@app.command("state")
def state(
    address: Annotated[str, typer.Option("--address")],
    new_status: Annotated[TaskStatus, typer.Option("--new-status")],
    reason: Annotated[str | None, typer.Option("--reason")] = None,
    force: Annotated[bool, typer.Option("--force")] = False,
    plan_dir: Annotated[Path | None, typer.Option("--plan-dir")] = None,
) -> None:
    """Move a task to a new status without a runner."""
    store = store_for(
        "state", legacy={"--plan-dir": plan_dir}, spec={"--reason": reason, "--force": force}, plan=raw_plan_of(address)
    )
    if store is Store.LEDGER:
        plan_ref, task_ref = _task_of(address)
        with _ledger() as conn:
            _emit_transition(
                ledger.state(conn, plan_ref, task_ref, new_status=str(new_status), reason=reason, force=force)
            )
        return
    backend = _backend()
    plan_ref, optional_task = _address(address, backend)
    if optional_task is None:
        _error(f"Address '{address}' does not include a task component")
    task_id = f"T{optional_task}" if optional_task.isdigit() else optional_task
    try:
        result = operations.update_task_status(backend, plan_ref, task_id, new_status)
    except (PlanNotFoundError, TaskNotFoundError, FileNotFoundError, FormatDetectionError) as exc:
        _error(str(exc), 2 if isinstance(exc, FormatDetectionError) else 1)
    _emit(result)

class ContentTaskProvider(InMemoryTaskProvider):
    """Persist the established in-memory task behavior through ContentProvider."""

    def __init__(self, provider: ContentProvider) -> None:
        """Load current logical plans from the configured provider."""
        super().__init__()
        self._provider = provider
        self._revisions: dict[str, str] = {}
        offset = 0
        while True:
            records = provider.list_content(
                ContentQuery(kind=ContentKind.PLAN, offset=offset, limit=_CONTENT_PAGE_SIZE)
            )
            for record in records:
                plan = parse_plan_content(record.content, record.reference.name)
                self._plans[plan["plan_id"]] = plan
                self._revisions[plan["plan_id"]] = record.revision
            if len(records) < _CONTENT_PAGE_SIZE:
                break
            offset += len(records)

    def _flush(self, plan_id: str, owner_reference: str | None = None) -> None:
        record = self._provider.put_content(
            ContentWrite(
                reference=ContentRef(kind=ContentKind.PLAN, name=plan_id),
                content=json.dumps(self._plans[plan_id], separators=(",", ":"), default=str),
                owner_reference=owner_reference,
                expected_revision=self._revisions.get(plan_id, ""),
            )
        )
        self._revisions[plan_id] = record.revision

